mapper.select:
SELECT p.word_id
FROM student_word_progress p
         INNER JOIN word_book_item wbi
                    ON wbi.word_id = p.word_id
                        AND wbi.book_id = #{bookId}
WHERE p.student_id = #{studentId}
  AND p.class_id = #{classId}
  AND p.status IN ('NEW', 'LEARNING')
ORDER BY p.created_at ASC, p.id ASC
